configuration.expression:
var ch = channel != null ? ('' + channel).trim().toUpperCase() : '';
var res = {};
if (ch == 'A') {
    res.voltage_A = voltage;
    res.current_A = current;
    res.power_A = power;
    res.temp_A = temp;
} else if (ch == 'B') {
    res.voltage_B = voltage;
    res.current_B = current;
    res.power_B = power;
    res.temp_B = temp;
} else if (ch == 'C') {
    res.voltage_C = voltage;
    res.current_C = current;
    res.power_C = power;
    res.temp_C = temp;
} else if (ch == 'D') {
    res.voltage_D = voltage;
    res.current_D = current;
    res.power_D = power;
    res.temp_D = temp;
}
return res;
